con:config.script:
// Функции генерации
function generateRandomUUID() {
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
        var r = Math.random() * 16 | 0;
        var v = c == 'x' ? r : (r & 0x3 | 0x8);
        return v.toString(16);
    });
}

function generateRandomColor() {
    var colors = ["Красный", "Синий", "Зеленый", "Желтый", "Черный", "Белый", "Фиолетовый", "Оранжевый", "Розовый", "Коричневый", "Серый", "Голубой"];
    return colors[Math.floor(Math.random() * colors.length)];
}

function generateRandomAbbreviation() {
    var letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    var abbreviation = "";
    for (var i = 0; i < 3; i++) {
        abbreviation += letters.charAt(Math.floor(Math.random() * letters.length));
    }
    return abbreviation;
}

function generateRandomAvatarImage() {
    var avatars = [
        "https://example.com/avatars/avatar1.png",
        "https://example.com/avatars/avatar2.png",
        "https://example.com/avatars/avatar3.png",
        "https://example.com/avatars/avatar4.png",
        "https://example.com/avatars/avatar5.png"
    ];
    return avatars[Math.floor(Math.random() * avatars.length)];
}

function generateRandomUrl() {
    var domains = ["example.com", "test.com", "demo.org", "sample.net", "store.ru"];
    var paths = ["product", "item", "goods", "shop", "store"];
    var domain = domains[Math.floor(Math.random() * domains.length)];
    var path = paths[Math.floor(Math.random() * paths.length)];
    var id = Math.floor(Math.random() * 10000);
    return "https://" + domain + "/" + path + "/" + id;
}

function generateRandomInt() {
    return Math.floor(Math.random() * 1000) + 1; // от 1 до 1000
}

// Генерация всех значений
var randomUUID = generateRandomUUID();
var randomColor = generateRandomColor();
var randomAbbreviation = generateRandomAbbreviation();
var randomAvatarImage = generateRandomAvatarImage();
var randomUrl = generateRandomUrl();
var randomInt = generateRandomInt();

// Сохранение на уровне проекта
var project = testRunner.testCase.testSuite.project;
project.setPropertyValue("randomUUID", randomUUID);
project.setPropertyValue("randomColor", randomColor);
project.setPropertyValue("randomAbbreviation", randomAbbreviation);
project.setPropertyValue("randomAvatarImage", randomAvatarImage);
project.setPropertyValue("randomUrl", randomUrl);
project.setPropertyValue("randomInt", randomInt.toString());

var testCase = testRunner.testCase;
var stepList = testCase.getTestStepList();

var requestName = null;
for (var i = 0; i < stepList.size(); i++) {
var step = stepList.get(i);
if (step.getClass().toString().indexOf("RestTestRequestStep") > -1) {
requestName = step.getName();
break;
}
}
if (!requestName) throw new Error("Не найден REST-запрос в тест-кейсе");

var responseBody = context.expand('${' + requestName + '#Response}');
if (!responseBody) throw new Error("Пустой ответ от запроса: " + requestName);

var ids = [], m;
var reStr = /"id"\s*:\s*"([^"]+)"/g;
while ((m = reStr.exec(responseBody)) !== null) ids.push(m[1]);
if (ids.length === 0) {
var reNum = /"id"\s*:\s*(\d+)/g;
while ((m = reNum.exec(responseBody)) !== null) ids.push(m[1]);
}
if (ids.length === 0) throw new Error("id не найден в ответе");

var lastId = ids[ids.length - 1];
testRunner.testCase.testSuite.project.setPropertyValue("lastId", lastId);

con:configuration.scriptText:
var responseBody = context.expand('${получение подарка по id#Response}');
var json = JSON.parse(responseBody);
var lastGift = json.wishList.gifts[json.wishList.gifts.length - 1];

var expected = {
    id: context.expand('${#Project#lastId}'),
    name: context.expand('${#Project#randomColor}'),
    description: context.expand('${#Project#randomAbbreviation}'),
    price: context.expand('${#Project#randomInt}'),
    storeUrl: context.expand('${#Project#randomUrl}'),
    imageUrl: context.expand('${#Project#randomAvatarImage}')
};

var checks = [
    {name: "ID", actual: lastGift.id, expected: expected.id},
    {name: "Name", actual: lastGift.name, expected: expected.name},
    {name: "Description", actual: lastGift.description, expected: expected.description},
    {name: "Price", actual: lastGift.price.toString(), expected: expected.price},
    {name: "Image URL", actual: lastGift.imageUrl, expected: expected.imageUrl},
    {name: "Reserved", actual: lastGift.reserved, expected: false}
];

var failed = [];
for (var i = 0; i < checks.length; i++) {
    var check = checks[i];
    if (check.actual != check.expected) {
        failed.push(check);
    }
}

if (failed.length > 0) {
    throw new Error("Проверки не пройдены: " + failed.length + " ошибок");
}

con:config.script:
var responseBody = context.expand('${получение подарка по id#Response}');

try {
    var json = JSON.parse(responseBody);
    var lastGiftReserved = json.wishList.gifts[json.wishList.gifts.length - 1].reserved;

    log.info("reserved последнего подарка = " + lastGiftReserved);

    // Сохраняем в свойство
    testRunner.testCase.testSuite.project.setPropertyValue("lastGiftReserved", lastGiftReserved.toString());

} catch (e) {
    log.error("Ошибка: " + e.message);
}

// Получаем тест-кейс
var testCase = testRunner.testCase;
var stepList = testCase.getTestStepList();

if (stepList.size() <= 1) {
    throw new Error("В тест-кейсе нет запроса!");
}

// Находим первый REST-запрос (не обязательно индекс 1)
var requestName = null;
for (var i = 0; i < stepList.size(); i++) {
    var step = stepList.get(i);
    if (step.getClass().toString().indexOf("RestTestRequestStep") > -1) {
        requestName = step.getName();
        log.info("Найден REST-запрос на шаге " + i + ": '" + requestName + "'");
        break;
    }
}

if (!requestName) {
    throw new Error("Не найден REST-запрос в тест-кейсе!");
}

// Получаем статус и ответ
var statusCode = context.expand('${' + requestName + '#ResponseStatusCode}');
var responseBody = context.expand('${' + requestName + '#Response}');

log.info("Статус код: '" + statusCode + "'");
log.info("Длина ответа: " + responseBody.length);

// Если ответ не пустой, извлекаем последний id
try {
    log.info("Ответ: " + responseBody);

    // Находим ВСЕ id в ответе
    var idMatches = responseBody.match(/"id"\s*:\s*"([^"]+)"/g);

    if (idMatches && idMatches.length > 0) {
        log.info("Найдено id: " + idMatches.length);      

        // Берем ПОСЛЕДНИЙ id (с конца)
        var lastIdMatch = idMatches[idMatches.length - 1];

        // Извлекаем значение последнего id
        var lastIdValueMatch = lastIdMatch.match(/"id"\s*:\s*"([^"]+)"/);

        if (lastIdValueMatch && lastIdValueMatch[1]) {
            var lastId = lastIdValueMatch[1];            
            // Сохраняем
            testRunner.testCase.testSuite.project.setPropertyValue("lastId", lastId);
            log.info("✓ lastId сохранен в свойство проекта");
            // Проверяем
            var savedId = testRunner.testCase.testSuite.project.getPropertyValue("lastId");
            log.info("✓ Проверка: lastId = " + savedId);
        } else {
            log.error("Не удалось извлечь значение последнего id");
        }
    } else {
        // Альтернативный вариант: ищем id без кавычек (для числовых id)
        log.info("Пробуем найти числовые id...");
        var numericIdMatches = responseBody.match(/"id"\s*:\s*(\d+)/g);

        if (numericIdMatches && numericIdMatches.length > 0) {
            var lastNumericMatch = numericIdMatches[numericIdMatches.length - 1];
            var lastNumericValue = lastNumericMatch.match(/"id"\s*:\s*(\d+)/);

            if (lastNumericValue && lastNumericValue[1]) {
                var lastId = lastNumericValue[1];
                testRunner.testCase.testSuite.project.setPropertyValue("lastId", lastId);
            }
        } 
    }
} catch (e) {
    log.error("Ошибка: " + e.message);
}

// Функции генерации
function generateRandomUUID() {
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
        var r = Math.random() * 16 | 0;
        var v = c == 'x' ? r : (r & 0x3 | 0x8);
        return v.toString(16);
    });
}

function generateRandomColor() {
    var colors = ["Красный", "Синий", "Зеленый", "Желтый", "Черный", "Белый", "Фиолетовый", "Оранжевый", "Розовый", "Коричневый", "Серый", "Голубой"];
    return colors[Math.floor(Math.random() * colors.length)];
}

function generateRandomAbbreviation() {
    var letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    var abbreviation = "";
    for (var i = 0; i < 3; i++) {
        abbreviation += letters.charAt(Math.floor(Math.random() * letters.length));
    }
    return abbreviation;
}

function generateRandomAvatarImage() {
    var avatars = [
        "https://example.com/avatars/avatar1.png",
        "https://example.com/avatars/avatar2.png",
        "https://example.com/avatars/avatar3.png",
        "https://example.com/avatars/avatar4.png",
        "https://example.com/avatars/avatar5.png"
    ];
    return avatars[Math.floor(Math.random() * avatars.length)];
}

function generateRandomUrl() {
    var domains = ["example.com", "test.com", "demo.org", "sample.net", "store.ru"];
    var paths = ["product", "item", "goods", "shop", "store"];
    var domain = domains[Math.floor(Math.random() * domains.length)];
    var path = paths[Math.floor(Math.random() * paths.length)];
    var id = Math.floor(Math.random() * 10000);
    return "https://" + domain + "/" + path + "/" + id;
}

function generateRandomInt() {
    return Math.floor(Math.random() * 1000) + 1; // от 1 до 1000
}

// Генерация всех значений
var randomUUID = generateRandomUUID();
var randomColor = generateRandomColor();
var randomAbbreviation = generateRandomAbbreviation();
var randomAvatarImage = generateRandomAvatarImage();
var randomUrl = generateRandomUrl();
var randomInt = generateRandomInt();

// Сохранение на уровне проекта
var project = testRunner.testCase.testSuite.project;
project.setPropertyValue("randomUUID", randomUUID);
project.setPropertyValue("randomColor", randomColor);
project.setPropertyValue("randomAbbreviation", randomAbbreviation);
project.setPropertyValue("randomAvatarImage", randomAvatarImage);
project.setPropertyValue("randomUrl", randomUrl);
project.setPropertyValue("randomInt", randomInt.toString());

